INSERT INTO device_action (device_kind, action, label, params_schema, description, side_effect_class, is_default, effect_check) VALUES
  ('battery', 'charge', 'Charge', '{"charge_limit_pct":{"type":"number","unit":"%","min":0,"max":100,"required":true},"target_soc_kwh":{"type":"number","unit":"kWh","min":0},"power_w":{"type":"number","unit":"W","min":0},"power_fraction":{"type":"number","min":0,"max":1}}', 'Charges from the grid (and solar) up to charge_limit_pct; 0 means no charge (Predbat sentinel). power_w NULL = the inverter maximum.', 'energy', 0, '{"metric":"battery_charge_w","min":100,"afterS":300,"windowS":300,"already":{"metric":"battery_soc_pct","targetKeys":["target_soc_pct","limit_pct"]}}'),
  ('battery', 'demand', 'Demand (self-consumption)', '{}', 'Covers the home''s load from solar and the battery down to the reserve; surplus solar charges the battery, then exports. The normal mode, and the action of a slot with no row.', 'none', 1, NULL),
  ('battery', 'export', 'Export', '{"export_limit_pct":{"type":"number","unit":"%","min":0,"max":100,"required":true},"start_offset_min":{"type":"integer","unit":"min","min":0,"max":55},"power_w":{"type":"number","unit":"W","min":0},"power_fraction":{"type":"number","min":0,"max":1}}', 'Force-discharges to the grid down to the floor export_limit_pct (100 means no export). May start start_offset_min into its first slot (a multiple of 5, less than the slot); always ends on a slot boundary.', 'grid_export', 0, '{"metric":"grid_export_w","min":100,"afterS":300,"windowS":300}'),
  ('battery', 'force_discharge', 'Force discharge', '{"power_w":{"type":"number","unit":"W","min":0,"required":true},"export_limit_pct":{"type":"number","unit":"%","min":0,"max":100},"power_fraction":{"type":"number","min":0,"max":1}}', 'Discharges at power_w whatever the load (vendor forced discharge, for example a grid-service event or a manual override), down to the optional floor. export is the planner''s discharge-to-floor.', 'grid_export', 0, '{"metric":"grid_export_w","min":100,"afterS":300,"windowS":300}'),
  ('battery', 'freeze_charge', 'Freeze charge', '{}', 'Holds the charge level: the grid covers the load, surplus solar may still charge. Target = the charge level when the slot starts.', 'energy', 0, NULL),
  ('battery', 'freeze_export', 'Freeze export', '{}', 'Demand with charging disabled: the battery covers the load, surplus solar is exported, the charge level is not raised.', 'energy', 0, NULL),
  ('battery', 'hold', 'Hold', '{}', 'Neither charges nor discharges (vendor standby or hold mode): solar and grid cover the load. Not the derived hold-charging state, which the executor logs.', 'energy', 0, NULL),
  ('battery', 'pause', 'Pause', '{"what":{"type":"string","enum":["charge","discharge","both"],"required":true}}', 'Vendor pause mode: stops charging, discharging or both for the slot.', 'energy', 0, NULL),
  ('battery', 'release', 'Hand back', '{}', 'Hands the battery back (read-only mode or leaving the service): charge and export windows cleared, full rates, default reserve, confirmed by read-back (PB-CTRL-02).', 'none', 0, NULL),
  ('boiler', 'auto', 'Own controls', '{}', 'No instruction: the boiler follows its own schedule and set-point.', 'none', 1, NULL),
  ('boiler', 'boost', 'Boost', '{"minutes":{"type":"integer","unit":"min","min":5,"max":240,"required":true},"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30}}', 'As heat_pump boost.', 'comfort', 0, NULL),
  ('boiler', 'heat_off', 'Heating off', '{}', 'As heat_pump heat_off: frost protection must stay active.', 'safety', 0, NULL),
  ('boiler', 'heat_on', 'Heating on', '{}', 'As heat_pump heat_on.', 'comfort', 0, NULL),
  ('boiler', 'set_flow_temp', 'Set flow temperature', '{"flow_temp_c":{"type":"number","unit":"degC","min":20,"max":80,"required":true}}', 'As heat_pump set_flow_temp.', 'comfort', 0, NULL),
  ('boiler', 'set_target_temp', 'Set target temperature', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'As heat_pump set_target_temp.', 'comfort', 0, NULL),
  ('boiler', 'setback', 'Setback', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'As heat_pump setback.', 'comfort', 0, NULL),
  ('ev_charger', 'auto', 'Own schedule', '{}', 'No instruction: the charger follows its own schedule or the car''s.', 'none', 1, NULL),
  ('ev_charger', 'charge', 'Charge the car', '{"power_w":{"type":"number","unit":"W","min":0},"target_soc_pct":{"type":"number","unit":"%","min":0,"max":100}}', 'Charges the car at power_w (NULL = the charger maximum), optionally up to the car''s target_soc_pct.', 'energy', 0, NULL),
  ('ev_charger', 'set_current', 'Set current', '{"current_a":{"type":"number","unit":"A","min":0,"max":80,"required":true}}', 'Sets the charging current (most AC chargers cannot go below 6 A; the device capability note says its own range).', 'energy', 0, NULL),
  ('ev_charger', 'stop', 'Stop charging', '{}', 'Stops or holds off charging for the slot.', 'energy', 0, NULL),
  ('heat_pump', 'auto', 'Own controls', '{}', 'No instruction: the heat pump follows its own schedule, set-point and weather compensation.', 'none', 1, NULL),
  ('heat_pump', 'boost', 'Boost', '{"minutes":{"type":"integer","unit":"min","min":5,"max":240,"required":true},"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30}}', 'Heats harder for a number of minutes (pre-heating before a peak).', 'comfort', 0, NULL),
  ('heat_pump', 'heat_off', 'Heating off', '{}', 'Space heating off for the slot. Frost protection must stay active (verified when the device is provisioned).', 'safety', 0, NULL),
  ('heat_pump', 'heat_on', 'Heating on', '{}', 'Space heating on (its own schedule and set-point).', 'comfort', 0, NULL),
  ('heat_pump', 'set_flow_temp', 'Set flow temperature', '{"flow_temp_c":{"type":"number","unit":"degC","min":20,"max":80,"required":true}}', 'Sets the flow temperature of the heating circuit.', 'comfort', 0, NULL),
  ('heat_pump', 'set_target_temp', 'Set target temperature', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'Sets the room set-point the heat pump controls to.', 'comfort', 0, NULL),
  ('heat_pump', 'setback', 'Setback', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'Lowers the set-point to setpoint_c (coasting through a peak price).', 'comfort', 0, NULL),
  ('hot_water', 'auto', 'Own schedule', '{}', 'No instruction: the hot water follows its own timer.', 'none', 1, NULL),
  ('hot_water', 'heat_water', 'Heat hot water', '{"setpoint_c":{"type":"number","unit":"degC","min":40,"max":80}}', 'Heats the cylinder (by whatever heats it) to setpoint_c, or its own target.', 'comfort', 0, NULL),
  ('iboost', 'auto', 'Own mode', '{}', 'No instruction: the diverter sends surplus solar to the cylinder as it normally does.', 'none', 1, NULL),
  ('iboost', 'off', 'Boost off', '{}', 'Diverts only solar surplus (its normal mode).', 'comfort', 0, NULL),
  ('iboost', 'on', 'Boost on', '{"power_w":{"type":"number","unit":"W","min":0}}', 'Boosts the cylinder from the grid, on top of the solar surplus it diverts.', 'energy', 0, NULL),
  ('immersion', 'auto', 'Own schedule', '{}', 'No instruction: the immersion follows its own timer or thermostat.', 'none', 1, NULL),
  ('immersion', 'off', 'Immersion off', '{}', 'Off: the cylinder is not heated by the immersion in this slot.', 'comfort', 0, NULL),
  ('immersion', 'on', 'Immersion on', '{"power_w":{"type":"number","unit":"W","min":0}}', 'Heats the hot-water cylinder from the grid.', 'energy', 0, NULL),
  ('inverter', 'charge', 'Charge', '{"charge_limit_pct":{"type":"number","unit":"%","min":0,"max":100,"required":true},"target_soc_kwh":{"type":"number","unit":"kWh","min":0},"power_w":{"type":"number","unit":"W","min":0},"power_fraction":{"type":"number","min":0,"max":1}}', 'As battery charge.', 'energy', 0, '{"metric":"battery_charge_w","min":100,"afterS":300,"windowS":300,"already":{"metric":"battery_soc_pct","targetKeys":["target_soc_pct","limit_pct"]}}'),
  ('inverter', 'demand', 'Demand (self-consumption)', '{}', 'As battery demand, for a hybrid inverter planned as the battery it controls.', 'none', 1, NULL),
  ('inverter', 'export', 'Export', '{"export_limit_pct":{"type":"number","unit":"%","min":0,"max":100,"required":true},"start_offset_min":{"type":"integer","unit":"min","min":0,"max":55},"power_w":{"type":"number","unit":"W","min":0},"power_fraction":{"type":"number","min":0,"max":1}}', 'As battery export.', 'grid_export', 0, '{"metric":"grid_export_w","min":100,"afterS":300,"windowS":300}'),
  ('inverter', 'force_discharge', 'Force discharge', '{"power_w":{"type":"number","unit":"W","min":0,"required":true},"export_limit_pct":{"type":"number","unit":"%","min":0,"max":100},"power_fraction":{"type":"number","min":0,"max":1}}', 'As battery force_discharge.', 'grid_export', 0, '{"metric":"grid_export_w","min":100,"afterS":300,"windowS":300}'),
  ('inverter', 'freeze_charge', 'Freeze charge', '{}', 'As battery freeze_charge.', 'energy', 0, NULL),
  ('inverter', 'freeze_export', 'Freeze export', '{}', 'As battery freeze_export.', 'energy', 0, NULL),
  ('inverter', 'hold', 'Hold', '{}', 'As battery hold.', 'energy', 0, NULL),
  ('inverter', 'pause', 'Pause', '{"what":{"type":"string","enum":["charge","discharge","both"],"required":true}}', 'As battery pause.', 'energy', 0, NULL),
  ('inverter', 'release', 'Hand back', '{}', 'As battery release.', 'none', 0, NULL),
  ('thermostat', 'auto', 'Own schedule', '{}', 'No instruction: the thermostat follows its own schedule.', 'none', 1, NULL),
  ('thermostat', 'set_target_temp', 'Set target temperature', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'Sets the room thermostat''s set-point.', 'comfort', 0, NULL),
  ('trv', 'auto', 'Own schedule', '{}', 'No instruction: the valve follows its own schedule.', 'none', 1, NULL),
  ('trv', 'set_target_temp', 'Set target temperature', '{"setpoint_c":{"type":"number","unit":"degC","min":5,"max":30,"required":true}}', 'Sets one radiator valve''s set-point.', 'comfort', 0, NULL);
